const joinedLabel = (n: { props: { children?: unknown } }): string => {
  const parts: string[] = [];
  const walk = (v: unknown): void => {
    if (typeof v === "string") parts.push(v);
    else if (Array.isArray(v)) v.forEach(walk);
  };
  walk(n.props.children);
  return parts.join("");
};

