    mockedApi.notes.mockResolvedValueOnce({
      notes: [{
        id: "overflow-note", client_note_id: "overflow-note", pattern_pid: null, blob: "b",
        created_at: "2026-09-16T00:00:00Z", updated_at: "2026-09-16T00:00:00Z",
      }],
      nextOffset: 21,
